import cronexpr as c

random.seed(7)

def brute(expr, after, max_days=400):
    text = c._SHORTCUTS.get(expr.strip().lower(), expr.strip())
    f = text.split()
    mins = sorted(c._parse_field(f[0], 0, 59, None))
    hrs = sorted(c._parse_field(f[1], 0, 23, None))
    doms = c._parse_field(f[2], 1, 31, None)
    mons = c._parse_field(f[3], 1, 12, c._MONTH_NAMES)
    dows = {0 if v == 7 else v for v in c._parse_field(f[4], 0, 7, c._DOW_NAMES)}
    domr, dowr = f[2] != "*", f[4] != "*"
    cur = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    end = cur + timedelta(days=max_days)
    while cur < end:
        ok = False
        if cur.month in mons:
            dm = cur.day in doms
            dw = (cur.weekday() + 1) % 7 in dows
            ok = (dm or dw) if (domr and dowr) else (dm if domr else (dw if dowr else True))
        if ok and cur.minute in mins and cur.hour in hrs:
            return cur
        cur += timedelta(minutes=1)
    return None

atoms = ["*", "0", "5", "10", "15", "30", "59", "1-5", "0-7", "*/2", "*/15", "5/20", "1-31", "1-12", "MON-FRI", "SUN", "7", "5-7", "JAN", "JAN-MAR", "1,15", "0,30"]
fixed = [("*/15 * * * *",), ("0 9 * * MON-FRI",), ("30 4 1,15 * 5",), ("0 0 29 2 *",)]

def field_for(idx):
    while True:
        e = random.choice(atoms)
        try:
            low, high, names = [(0,59,None),(0,23,None),(1,31,None),(1,12,c._MONTH_NAMES),(0,7,c._DOW_NAMES)][idx]
            c._parse_field(e, low, high, names)
            # reject names in wrong fields
            if idx not in (3,4) and any(ch.isalpha() for ch in e):
                continue
            if idx == 3 and e in ("SUN","MON-FRI","7","5-7"):
                continue
            if idx == 4 and e in ("JAN","JAN-MAR"):
                continue
            return e
        except ValueError:
            pass

mismatch = 0
for i in range(3000):
    expr = " ".join(field_for(j) for j in range(5))
    after = datetime(2026, 1, 1) + timedelta(minutes=random.randrange(0, 60*24*365*2))
    expected = brute(expr, after)
    try:
        got = c.next_run(expr, after)
    except ValueError:
        got = None
    if expected is not None and expected <= after.replace(second=0, microsecond=0) + timedelta(days=400):
        if got != expected:
            mismatch += 1
            print("MISMATCH", expr, after, "got", got, "expected", expected)
            if mismatch > 10:
                break
print("random comparisons done, mismatches:", mismatch)
