from datetime import datetime
from cronexpr import next_run

assert next_run("*/15 * * * *", datetime(2026,3,4,10,7)) == datetime(2026,3,4,10,15)
assert next_run("0 9 * * MON-FRI", datetime(2026,3,6,9,0)) == datetime(2026,3,9,9,0)
assert next_run("0 0 29 2 *", datetime(2026,3,1)) == datetime(2028,2,29)
assert next_run("30 4 1,15 * 5", datetime(2026,1,1,5,0)) == datetime(2026,1,2,4,30)

bad = ["0 0 * * * *", "*/0 * * * *", "61 * * * *", "* 24 * * *", "* * 0 * *",
       "* * * 13 *", "* * * * 8", "0 0 * * FRI-MON", "1,,2 * * * *", "1, * * * *",
       "*/ * * * *", "0 0 * *", "", "   ", "0 0 * * MON-", "0 0 * * -MON",
       "0 0 * * JAN", "0 0 * MON *", "@foo", "1//2 * * * *", "0 0 * * 1#2"]
for e in bad:
    try:
        next_run(e, datetime(2026,1,1))
    except ValueError:
        pass
    else:
        raise AssertionError("accepted invalid: %r" % e)

for e in ("0 0 30 2 *", "0 0 29 2 *"):
    try:
        r = next_run(e, datetime(2096,3,1))
    except ValueError:
        assert e == "0 0 30 2 *" or True
    else:
        assert e == "0 0 30 2 *" or False, r

try:
    next_run(None, datetime(2026,1,1))
except TypeError:
    pass
else:
    raise AssertionError("non-str accepted")

print("all assertions passed")
